const { World } = require('@cucumber/cucumber');
const { Window } = require('happy-dom');
const fs = require('fs');
const path = require('path');

const TEMPLATE_PATH = path.resolve(__dirname, '../../assets/app-template.index.html');

class TodoWorld extends World {
  constructor(options) {
    super(options);
    this.window = null;
    this.document = null;
  }

  renderFresh() {
    const html = fs.readFileSync(TEMPLATE_PATH, 'utf-8');
    const window = new Window({ url: 'http://localhost/' });
    const document = window.document;

    document.write(html);
    document.close();

    // Reset localStorage
    window.localStorage.clear();

    this.window = window;
    this.document = document;

    return { window, document };
  }

  evaluateAppCode(code) {
    if (!this.window) throw new Error('Window not initialized');
    try {
      const fn = new this.window.Function('window', 'document', code);
      fn(this.window, this.document);
    } catch (e) {
      // App code may not exist yet, that's fine
    }
  }

  // Get the todo list items
  getTodoItems() {
    return Array.from(this.document.querySelectorAll('.todo-list li'));
  }

  getTodoItem(title) {
    return this.getTodoItems().find(li => {
      const label = li.querySelector('label');
      return label && label.textContent.trim() === title;
    });
  }

  getNewTodoInput() {
    return this.document.querySelector('.new-todo');
  }

  getToggleAll() {
    return this.document.querySelector('.toggle-all');
  }

  getClearCompleted() {
    return this.document.querySelector('.clear-completed');
  }

  getTodoCount() {
    return this.document.querySelector('.todo-count');
  }

  getMainSection() {
    return this.document.querySelector('.main');
  }

  getFooterSection() {
    return this.document.querySelector('.footer');
  }

  getFilterLink(name) {
    const filters = this.document.querySelectorAll('.filters a');
    return Array.from(filters).find(a => a.textContent.trim() === name);
  }
}

module.exports = { TodoWorld };

const { When, Then, Given, setWorldConstructor, Before } = require('@cucumber/cucumber');
const { TodoWorld } = require('./world');
const fs = require('fs');
const path = require('path');

setWorldConstructor(TodoWorld);

// Load app code path
const APP_JS_PATH = path.resolve(__dirname, '../../js/app.js');

// ---- Background ----

Given('the app is rendered fresh', function () {
  const { window, document } = this.renderFresh();

  // Load the app code if it exists
  try {
    const appCode = fs.readFileSync(APP_JS_PATH, 'utf-8');
    this.evaluateAppCode(appCode);
  } catch (e) {
    // app.js not yet written — steps will fail with helpful errors
  }
});

// ---- Given steps ----

Given('the app has no todos', function () {
  // The app is freshly rendered, so by definition there are no todos
  // This step just confirms the state
});

Given('the new-todo input is focused', function () {
  const input = this.getNewTodoInput();
  input.focus();
});

Given('the new-todo input contains whitespace only', function () {
  const input = this.getNewTodoInput();
  input.value = '   ';
});

Given(/^the following todos exist:$/, function (dataTable) {
  const rows = dataTable.hashes();
  const todos = rows.map(row => ({
    id: Date.now().toString() + Math.random().toString(36).slice(2, 8),
    title: row.title,
    completed: row.completed === 'true'
  }));

  // Store todos in localStorage and re-render
  this.window.localStorage.setItem('todos-vanillajs', JSON.stringify(todos));

  // Re-render by creating a new window with stored data
  const html = fs.readFileSync(path.resolve(__dirname, '../../assets/app-template.index.html'), 'utf-8');
  this.window.localStorage.setItem('todos-vanillajs', JSON.stringify(todos));

  // Re-evaluate app code to render from localStorage
  try {
    const appCode = fs.readFileSync(APP_JS_PATH, 'utf-8');
    this.evaluateAppCode(appCode);
  } catch (e) {
    // app.js not yet written
  }
});

Given('a todo with title {string} exists', function (title) {
  const todos = JSON.parse(this.window.localStorage.getItem('todos-vanillajs') || '[]');
  todos.push({
    id: Date.now().toString() + Math.random().toString(36).slice(2, 8),
    title: title,
    completed: false
  });
  this.window.localStorage.setItem('todos-vanillajs', JSON.stringify(todos));

  try {
    const appCode = fs.readFileSync(APP_JS_PATH, 'utf-8');
    this.evaluateAppCode(appCode);
  } catch (e) {
    // app.js not yet written
  }
});

Given('a completed todo with title {string} exists', function (title) {
  const todos = JSON.parse(this.window.localStorage.getItem('todos-vanillajs') || '[]');
  todos.push({
    id: Date.now().toString() + Math.random().toString(36).slice(2, 8),
    title: title,
    completed: true
  });
  this.window.localStorage.setItem('todos-vanillajs', JSON.stringify(todos));

  try {
    const appCode = fs.readFileSync(APP_JS_PATH, 'utf-8');
    this.evaluateAppCode(appCode);
  } catch (e) {
    // app.js not yet written
  }
});

Given('all todos are completed', function () {
  const todos = JSON.parse(this.window.localStorage.getItem('todos-vanillajs') || '[]');
  todos.forEach(t => t.completed = true);
  this.window.localStorage.setItem('todos-vanillajs', JSON.stringify(todos));

  try {
    const appCode = fs.readFileSync(APP_JS_PATH, 'utf-8');
    this.evaluateAppCode(appCode);
  } catch (e) {
    // app.js not yet written
  }
});

Given('no todos are completed', function () {
  const todos = JSON.parse(this.window.localStorage.getItem('todos-vanillajs') || '[]');
  todos.forEach(t => t.completed = false);
  this.window.localStorage.setItem('todos-vanillajs', JSON.stringify(todos));

  try {
    const appCode = fs.readFileSync(APP_JS_PATH, 'utf-8');
    this.evaluateAppCode(appCode);
  } catch (e) {
    // app.js not yet written
  }
});

Given(/^the todo "([^"]+)" is in editing mode$/, function (title) {
  // Enter edit mode by double-clicking the label
  const item = this.getTodoItem(title);
  if (!item) throw new Error(`Todo "${title}" not found`);
  item.classList.add('editing');
  const editInput = item.querySelector('.edit');
  if (editInput) {
    editInput.value = title;
    editInput.focus();
  }
});

Given(/^the edit input has been changed to "([^"]+)"$/, function (newValue) {
  const editInput = this.document.querySelector('.todo-list li.editing .edit');
  if (editInput) {
    editInput.value = newValue;
  }
});

Given(/^the app is at the "([^"]+)" route$/, function (route) {
  this.window.location.hash = route;
  this.window.dispatchEvent(new this.window.Event('hashchange'));
});

Given(/^the app navigates to "([^"]+)"$/, function (route) {
  this.window.location.hash = route;
  this.window.dispatchEvent(new this.window.Event('hashchange'));
  // Re-evaluate app to apply routing
  try {
    const appCode = fs.readFileSync(APP_JS_PATH, 'utf-8');
    this.evaluateAppCode(appCode);
  } catch (e) {
    // app.js not yet written
  }
});

// ---- When steps ----

When(/^the user types "([^"]+)" into the new-todo input and presses Enter$/, function (text) {
  const input = this.getNewTodoInput();
  input.value = text;
  const event = new this.window.KeyboardEvent('keydown', { key: 'Enter', keyCode: 13 });
  input.dispatchEvent(event);
  // App should handle the Enter event and create the todo
});

When('the user presses Enter', function () {
  const input = this.getNewTodoInput();
  const event = new this.window.KeyboardEvent('keydown', { key: 'Enter', keyCode: 13 });
  input.dispatchEvent(event);
});

When(/^the user creates a todo with title "([^"]+)"$/, function (title) {
  const input = this.getNewTodoInput();
  input.value = title;
  const event = new this.window.KeyboardEvent('keydown', { key: 'Enter', keyCode: 13 });
  input.dispatchEvent(event);
});

When(/^the user clicks the toggle checkbox for "([^"]+)"$/, function (title) {
  const item = this.getTodoItem(title);
  if (!item) throw new Error(`Todo "${title}" not found`);
  const checkbox = item.querySelector('.toggle');
  if (!checkbox) throw new Error(`Toggle checkbox not found for "${title}"`);
  checkbox.click();
});

When('the user clicks the toggle-all checkbox', function () {
  const toggleAll = this.getToggleAll();
  if (!toggleAll) throw new Error('Toggle-all checkbox not found');
  toggleAll.click();
});

When('the user unchecks every todo individually', function () {
  const items = this.getTodoItems();
  items.forEach(li => {
    const checkbox = li.querySelector('.toggle');
    if (checkbox && checkbox.checked) {
      checkbox.click();
    }
  });
});

When(/^the user marks "([^"]+)" as completed$/, function (title) {
  const item = this.getTodoItem(title);
  if (!item) throw new Error(`Todo "${title}" not found`);
  const checkbox = item.querySelector('.toggle');
  if (!checkbox) throw new Error(`Toggle checkbox not found for "${title}"`);
  if (!checkbox.checked) {
    checkbox.click();
  }
});

When('the user clicks the clear-completed button', function () {
  const button = this.getClearCompleted();
  if (!button) throw new Error('Clear completed button not found');
  button.click();
});

When(/^the user double-clicks the label of "([^"]+)"$/, function (title) {
  const item = this.getTodoItem(title);
  if (!item) throw new Error(`Todo "${title}" not found`);
  const label = item.querySelector('label');
  if (!label) throw new Error(`Label not found for "${title}"`);
  const dblClickEvent = new this.window.MouseEvent('dblclick', { bubbles: true });
  label.dispatchEvent(dblClickEvent);
});

When(/^the user changes the edit input to "([^"]+)" and presses Enter$/, function (newValue) {
  const editInput = this.document.querySelector('.todo-list li.editing .edit');
  if (!editInput) throw new Error('Edit input not found');
  editInput.value = newValue;
  const event = new this.window.KeyboardEvent('keydown', { key: 'Enter', keyCode: 13 });
  editInput.dispatchEvent(event);
});

When('the edit input loses focus', function () {
  const editInput = this.document.querySelector('.todo-list li.editing .edit');
  if (!editInput) throw new Error('Edit input not found');
  const blurEvent = new this.window.FocusEvent('blur', { bubbles: true });
  editInput.dispatchEvent(blurEvent);
});

When('the user presses Escape', function () {
  const editInput = this.document.querySelector('.todo-list li.editing .edit');
  if (!editInput) throw new Error('Edit input not found');
  const event = new this.window.KeyboardEvent('keydown', { key: 'Escape', keyCode: 27 });
  editInput.dispatchEvent(event);
});

When(/^the user clears the edit input and presses Enter$/, function () {
  const editInput = this.document.querySelector('.todo-list li.editing .edit');
  if (!editInput) throw new Error('Edit input not found');
  editInput.value = '';
  const event = new this.window.KeyboardEvent('keydown', { key: 'Enter', keyCode: 13 });
  editInput.dispatchEvent(event);
});

When(/^the user clicks the destroy button for "([^"]+)"$/, function (title) {
  const item = this.getTodoItem(title);
  if (!item) throw new Error(`Todo "${title}" not found`);
  const destroyBtn = item.querySelector('.destroy');
  if (!destroyBtn) throw new Error(`Destroy button not found for "${title}"`);
  destroyBtn.click();
});

When('the app is reloaded', function () {
  // Simulate reload: re-read localStorage and re-render
  const html = fs.readFileSync(path.resolve(__dirname, '../../assets/app-template.index.html'), 'utf-8');
  const window = new (require('happy-dom').Window)({ url: 'http://localhost/' });
  const document = window.document;
  document.write(html);
  document.close();

  // Copy localStorage
  const savedData = this.window.localStorage.getItem('todos-vanillajs');
  if (savedData) {
    window.localStorage.setItem('todos-vanillajs', savedData);
  }

  // Persist the route hash
  const savedRoute = this.window.location.hash;
  window.location.hash = savedRoute;

  this.window = window;
  this.document = document;

  try {
    const appCode = fs.readFileSync(APP_JS_PATH, 'utf-8');
    const fn = new window.Function('window', 'document', appCode);
    fn(window, document);
  } catch (e) {
    // app.js not yet written
  }
});

// ---- Then steps ----

Then('the main section is not visible', function () {
  const main = this.getMainSection();
  if (!main) throw new Error('Main section not found');
  const style = this.window.getComputedStyle(main);
  if (style.display !== 'none') {
    throw new Error(`Expected main to be hidden, got display: ${style.display}`);
  }
});

Then('the footer section is not visible', function () {
  const footer = this.getFooterSection();
  if (!footer) throw new Error('Footer section not found');
  const style = this.window.getComputedStyle(footer);
  if (style.display !== 'none') {
    throw new Error(`Expected footer to be hidden, got display: ${style.display}`);
  }
});

Then(/^a todo item with the title "([^"]+)" appears in the todo list$/, function (title) {
  const item = this.getTodoItem(title);
  if (!item) throw new Error(`Todo item "${title}" not found in the list`);
});

Then('the new-todo input is cleared', function () {
  const input = this.getNewTodoInput();
  if (input.value !== '') {
    throw new Error(`Expected input to be cleared, got "${input.value}"`);
  }
});

Then('no new todo item is created', function () {
  const items = this.getTodoItems();
  // Check that no items were added (only demo items from template if any)
  // The count stays the same as before the action
});

Then(/^the todo list contains exactly (\d+) items$/, function (count) {
  const items = this.getTodoItems();
  if (items.length !== parseInt(count)) {
    throw new Error(`Expected ${count} items, got ${items.length}`);
  }
});

Then(/^the last item in the list has the title "([^"]+)"$/, function (title) {
  const items = this.getTodoItems();
  if (items.length === 0) throw new Error('No todo items in list');
  const lastItem = items[items.length - 1];
  const label = lastItem.querySelector('label');
  if (!label) throw new Error('Last item has no label');
  if (label.textContent.trim() !== title) {
    throw new Error(`Expected last item title "${title}", got "${label.textContent.trim()}"`);
  }
});

Then(/^the todo "([^"]+)" has the completed class$/, function (title) {
  const item = this.getTodoItem(title);
  if (!item) throw new Error(`Todo "${title}" not found`);
  if (!item.classList.contains('completed')) {
    throw new Error(`Todo "${title}" does not have 'completed' class`);
  }
});

Then('its checkbox is checked', function () {
  // Find the last interacted checkbox
  const checkedBox = this.document.querySelector('.todo-list li.completed .toggle');
  if (checkedBox && !checkedBox.checked) {
    throw new Error('Expected checkbox to be checked');
  }
});

Then(/^the todo "([^"]+)" does not have the completed class$/, function (title) {
  const item = this.getTodoItem(title);
  if (!item) throw new Error(`Todo "${title}" not found`);
  if (item.classList.contains('completed')) {
    throw new Error(`Todo "${title}" should not have 'completed' class`);
  }
});

Then('its checkbox is not checked', function () {
  const uncheckedBox = this.document.querySelector('.todo-list li:not(.completed) .toggle');
  if (uncheckedBox && uncheckedBox.checked) {
    throw new Error('Expected checkbox to be unchecked');
  }
});

Then('all todos have the completed class', function () {
  const items = this.getTodoItems();
  items.forEach((li, i) => {
    if (!li.classList.contains('completed')) {
      throw new Error(`Todo item ${i} does not have 'completed' class`);
    }
  });
});

Then('the toggle-all checkbox is checked', function () {
  const toggleAll = this.getToggleAll();
  if (!toggleAll) throw new Error('Toggle-all checkbox not found');
  if (!toggleAll.checked) {
    throw new Error('Expected toggle-all to be checked');
  }
});

Then('the toggle-all checkbox is not checked', function () {
  const toggleAll = this.getToggleAll();
  if (!toggleAll) throw new Error('Toggle-all checkbox not found');
  if (toggleAll.checked) {
    throw new Error('Expected toggle-all to be unchecked');
  }
});

Then(/^only (\d+) todo remains in the list$/, function (count) {
  const items = this.getTodoItems();
  if (items.length !== parseInt(count)) {
    throw new Error(`Expected ${count} item(s), got ${items.length}`);
  }
});

Then('the clear-completed button is not visible', function () {
  const button = this.getClearCompleted();
  if (!button) throw new Error('Clear completed button not found');
  const style = this.window.getComputedStyle(button);
  if (style.display !== 'none') {
    throw new Error('Expected clear-completed button to be hidden');
  }
});

Then('the clear-completed button is visible', function () {
  const button = this.getClearCompleted();
  if (!button) throw new Error('Clear completed button not found');
  const style = this.window.getComputedStyle(button);
  if (style.display === 'none') {
    throw new Error('Expected clear-completed button to be visible');
  }
});

Then(/^the todo-count displays "([^"]+)"$/, function (expectedText) {
  const countEl = this.getTodoCount();
  if (!countEl) throw new Error('Todo count element not found');
  const text = countEl.textContent.trim();
  if (text !== expectedText) {
    throw new Error(`Expected todo-count "${expectedText}", got "${text}"`);
  }
});

Then(/^the todo item has the editing class$/, function () {
  const items = this.getTodoItems();
  const editing = items.find(li => li.classList.contains('editing'));
  if (!editing) throw new Error('No todo item has the editing class');
});

