(function (window, document) {
  'use strict';

  var ENTER_KEY = 13;
  var ESCAPE_KEY = 27;
  var STORAGE_KEY = 'todos-vanillajs';

  var todoApp = document.querySelector('.todoapp');
  var main = document.querySelector('.main');
  var footer = document.querySelector('.footer');
  var newTodo = document.querySelector('.new-todo');
  var todoList = document.querySelector('.todo-list');
  var toggleAll = document.querySelector('.toggle-all');
  var todoCount = document.querySelector('.todo-count');
  var clearCompleted = document.querySelector('.clear-completed');
  var filters = document.querySelector('.filters');

  var todos = [];
  var currentFilter = 'all';

  function loadTodos() {
    try {
      var data = window.localStorage.getItem(STORAGE_KEY);
      todos = data ? JSON.parse(data) : [];
    } catch (e) {
      todos = [];
    }
  }

  function saveTodos() {
    window.localStorage.setItem(STORAGE_KEY, JSON.stringify(todos));
  }

  function getId() {
    return Date.now().toString() + Math.random().toString(36).slice(2, 8);
  }

  function getFilteredTodos() {
    if (currentFilter === 'active') {
      return todos.filter(function (t) { return !t.completed; });
    }
    if (currentFilter === 'completed') {
      return todos.filter(function (t) { return t.completed; });
    }
    return todos;
  }

  function getActiveCount() {
    return todos.filter(function (t) { return !t.completed; }).length;
  }

  function getCompletedCount() {
    return todos.filter(function (t) { return t.completed; }).length;
  }

  function render() {
    var filtered = getFilteredTodos();
    var html = '';
    filtered.forEach(function (todo) {
      var liClass = '';
      if (todo.completed) liClass += 'completed';
      html += '<li' + (liClass ? ' class="' + liClass + '"' : '') + '>';
      html += '<div class="view">';
      html += '<input class="toggle" type="checkbox"' + (todo.completed ? ' checked' : '') + '>';
      html += '<label>' + escapeHtml(todo.title) + '</label>';
      html += '<button class="destroy"></button>';
      html += '</div>';
      html += '<input class="edit" value="' + escapeHtml(todo.title) + '">';
      html += '</li>';
    });
    todoList.innerHTML = html;

    // Update visibility
    var hasTodos = todos.length > 0;
    main.style.display = hasTodos ? '' : 'none';
    footer.style.display = hasTodos ? '' : 'none';

    // Update toggle-all
    var allCompleted = hasTodos && getActiveCount() === 0;
    toggleAll.checked = allCompleted;

    // Update counter
    var activeCount = getActiveCount();
    var word = activeCount === 1 ? 'item' : 'items';
    todoCount.innerHTML = '<strong>' + activeCount + '</strong> ' + word + ' left';

    // Update clear completed
    var completedCount = getCompletedCount();
    clearCompleted.style.display = completedCount > 0 ? '' : 'none';

    // Update filter links
    var filterLinks = filters.querySelectorAll('a');
    Array.prototype.forEach.call(filterLinks, function (a) {
      var href = a.getAttribute('href');
      if (href === '#/' && currentFilter === 'all') {
        a.classList.add('selected');
      } else if (href === '#/active' && currentFilter === 'active') {
        a.classList.add('selected');
      } else if (href === '#/completed' && currentFilter === 'completed') {
        a.classList.add('selected');
      } else {
        a.classList.remove('selected');
      }
    });
  }

  function escapeHtml(text) {
    var div = document.createElement('div');
    div.appendChild(document.createTextNode(text));
    return div.innerHTML;
  }

  function addTodo(title) {
    var trimmed = title.trim();
    if (trimmed === '') return;
    todos.push({
      id: getId(),
      title: trimmed,
      completed: false
    });
    saveTodos();
    render();
  }

  function removeTodo(id) {
    todos = todos.filter(function (t) { return t.id !== id; });
    saveTodos();
    render();
  }

  function toggleTodo(id) {
    todos.forEach(function (t) {
      if (t.id === id) t.completed = !t.completed;
    });
    saveTodos();
    render();
  }

  function toggleAllTodos() {
    var allCompleted = todos.length > 0 && getActiveCount() === 0;
    todos.forEach(function (t) { t.completed = !allCompleted; });
    saveTodos();
    render();
  }

  function clearCompletedTodos() {
    todos = todos.filter(function (t) { return !t.completed; });
    saveTodos();
    render();
  }

  function saveEdit(id, title) {
    var trimmed = title.trim();
    if (trimmed === '') {
      removeTodo(id);
      return;
    }
    todos.forEach(function (t) {
      if (t.id === id) t.title = trimmed;
    });
    saveTodos();
    render();
  }

  function setFilter(filter) {
    currentFilter = filter;
    window.localStorage.setItem(STORAGE_KEY + '-filter', filter);
    render();
  }

  function loadFilter() {
    try {
      var saved = window.localStorage.getItem(STORAGE_KEY + '-filter');
      if (saved) currentFilter = saved;
    } catch (e) {}
  }

  // Event delegation for todo list
  todoList.addEventListener('click', function (e) {
    var li = e.target.closest('li');
    if (!li) return;
    var todoId = todos[Array.prototype.indexOf.call(todoList.children, li)];

    if (e.target.classList.contains('toggle')) {
      toggleTodo(todoId ? todoId.id : null);
    }

    if (e.target.classList.contains('destroy')) {
      removeTodo(todoId ? todoId.id : null);
    }
  });

  todoList.addEventListener('dblclick', function (e) {
    var label = e.target.closest('label');
    if (!label) return;
    var li = label.closest('li');
    if (!li) return;
    li.classList.add('editing');
    var editInput = li.querySelector('.edit');
    editInput.focus();
    editInput.value = label.textContent;
  });

  todoList.addEventListener('focusout', function (e) {
    var editInput = e.target.closest('.edit');
    if (!editInput) return;
    var li = editInput.closest('li');
    if (!li) return;
    if (!li.classList.contains('editing')) return;
    var todoId = todos[Array.prototype.indexOf.call(todoList.children, li)];
    saveEdit(todoId ? todoId.id : null, editInput.value);
  });

  todoList.addEventListener('keydown', function (e) {
    var editInput = e.target.closest('.edit');
    if (!editInput) return;
    var li = editInput.closest('li');
    if (!li) return;

    if (e.keyCode === ENTER_KEY) {
      e.preventDefault();
      var todoId = todos[Array.prototype.indexOf.call(todoList.children, li)];
      saveEdit(todoId ? todoId.id : null, editInput.value);
    }

    if (e.keyCode === ESCAPE_KEY) {
      e.preventDefault();
      li.classList.remove('editing');
    }
  });

  // New todo input
  newTodo.addEventListener('keydown', function (e) {
    if (e.keyCode === ENTER_KEY) {
      e.preventDefault();
      addTodo(newTodo.value);
      newTodo.value = '';
    }
  });

  // Toggle all
  toggleAll.addEventListener('click', function () {
    toggleAllTodos();
  });

  // Clear completed
  clearCompleted.addEventListener('click', function () {
    clearCompletedTodos();
  });

  // Filter clicks
  filters.addEventListener('click', function (e) {
    var a = e.target.closest('a');
    if (!a) return;
    e.preventDefault();
    var href = a.getAttribute('href');
    if (href === '#/' || href === '#!/') setFilter('all');
    else if (href === '#/active') setFilter('active');
    else if (href === '#/completed') setFilter('completed');
  });

  // Hash change
  window.addEventListener('hashchange', function () {
    var hash = window.location.hash;
    if (hash === '#/' || hash === '' || hash === '#!/') setFilter('all');
    else if (hash === '#/active') setFilter('active');
    else if (hash === '#/completed') setFilter('completed');
  });

  // Initialize
  loadTodos();
  loadFilter();
  render();

})(typeof window !== 'undefined' ? window : {}, typeof document !== 'undefined' ? document : {});

